//! Frozen actual expiry source versus unique shared algorithm and complete native DATA.
pub use dq_analyze::{lint,incr,tree,pat,pat_match,util,parity,scopes,captured_generator_budget};
pub use dq_analyze::original_policy_descriptors as allow_registry_fields;
pub mod dm{pub use dq_analyze::dm::*;}
#[path="../fixtures/original_policies/expiry_workspace.rs"]mod old_expiry;
#[path="../fixtures/native-expiry-workspace/fixture.rs"]mod fixture;
#[path="../../dmb/shared/test_scratch.rs"]mod test_scratch;
use std::{path::Path,sync::Arc};
use dq_analyze::captured_raw_tree_pages::{Policy,Data};
struct Pages<'a>{root:&'a Path,rows:Vec<(String,dm_preprocess::SourceText)>,budget:Arc<dq_analyze::captured_generator_budget::Budget>}
impl dq_analyze::reactive_raw_policy_pages::RawPolicyPages for Pages<'_>{fn for_each(&self,visit:&mut dyn FnMut(&str,dq_analyze::captured_raw_file::RawPolicyViews<'_>)->Result<bool,dq_analyze::captured_reactive_reads::Failure>)->Result<bool,dq_analyze::captured_reactive_reads::Failure>{for(relative,text)in &self.rows{if !dq_analyze::captured_raw_file::with_original_policy_file(self.root,&self.root.join(relative),text.clone(),0,&self.budget,visit)?{return Ok(false)}}Ok(true)}}
struct Text<'a>(&'a Data);impl dq_analyze::baseline::SiteText for Text<'_>{fn site_text(&self,rel:&str,line:usize)->String{self.0.sites().iter().zip(self.0.source_text()).find(|(site,_)|site.rel==rel&&site.line as usize==line).map(|(_,text)|text.clone()).expect("actual delivered raw-tree source line absent")}}
fn record(outcome:&dq_analyze::policy_finish::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
fn register_old(name:&str,r:&mut lint::Registry){assert_eq!(name,"sys/expiry");old_expiry::register(r)}
fn register_shared(name:&str,r:&mut lint::Registry){assert_eq!(name,"sys/expiry");dq_analyze::lints::sys_expiry::register(r)}
fn failure(error:dq_analyze::captured_reactive_reads::Failure)->Box<dyn std::error::Error>{match error{dq_analyze::captured_reactive_reads::Failure::Operational(actual)=>Box::new(actual),dq_analyze::captured_reactive_reads::Failure::Unsupported(message)=>message.into()}}
fn main()->Result<(),Box<dyn std::error::Error>>{use sha1::Digest as _;
assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/expiry_workspace.rs"))),"43458929370f5986a925464d5e3901e43542f9c2");
for kind in fixture::KINDS{for case in 0..5{let name=fixture::name(kind);let policy=Policy::Expiry;let root=test_scratch::dir(&format!("expiry-{kind}-{case}"));let files=fixture::files(kind,case);for(relative,text)in &files{let path=root.join(relative);std::fs::create_dir_all(path.parent().ok_or("fixture parent")?)?;std::fs::write(path,text)?;}let configuration=fixture::configuration(kind,case);let path=root.join("tools/ci/lint_scopes.toml");std::fs::create_dir_all(path.parent().ok_or("config parent")?)?;std::fs::write(path,&configuration)?;
let options=dq_analyze::run::Options{root:root.clone(),lints:vec![name.into()],raw:true,no_cache:true,..Default::default()};let mut r=lint::Registry::default();register_old(name,&mut r);let old=dq_analyze::run::Engine::new(r,options.clone())?;let expected=old.run_one(old.reg.lints[0].as_ref());assert!(expected.internal_error.is_none(),"{kind}/{case}: {:?}",expected.internal_error);if case==0{assert!(!expected.run.sites.is_empty());assert!(!expected.allow_used.is_empty());assert!(expected.run.sites.iter().any(|s|s.rel=="maps/z.dm"));assert!(!expected.run.sites.iter().any(|s|s.rel.contains(".hidden")||s.rel.contains("unit_tests")));}if case==0{let names:Vec<_>=expected.allow_used.iter().map(|u|u.name.as_str()).collect();let outer=names.iter().position(|n|n.starts_with("sys_")).expect("genuine outer Sys annotation");assert!(names[..outer].iter().all(|n|*n=="cooldown"));assert!(!names[outer..].contains(&"cooldown"));assert!(expected.run.sites.iter().any(|s|s.rule=="world_time_expiry"));assert!(expected.run.sites.iter().any(|s|s.rule=="world_time_write"));assert!(expected.run.sites.iter().any(|s|s.rule=="expiry_undeclared"));assert!(!expected.run.sites.iter().any(|s|s.rel=="code/datums/om/decl.dm"));}let mut r=lint::Registry::default();register_shared(name,&mut r);let shared=dq_analyze::run::Engine::new(r,options)?;let actual_shared=shared.run_one(shared.reg.lints[0].as_ref());assert_eq!(record(&actual_shared),record(&expected),"entire independently frozen original/shared {kind}/{case}");
let budget=dq_analyze::captured_generator_budget::Budget::new(256*1024*1024)?;let mut rows=Vec::new();for(relative,text)in files{if !policy.selects_path(relative){continue}let source=dm_preprocess::AcquiredSource::from_original_bytes(text.into_bytes(),());rows.push((relative.to_string(),source.lease().source_text().clone()));}rows.reverse();let pages=Pages{root:&root,rows,budget:Arc::clone(&budget)};let config=dq_analyze::captured_raw_file::Config::capture(dq_analyze::captured_raw_policy::Configuration::Captured(configuration.as_bytes()))?;let data=dq_analyze::captured_raw_tree_pages::collect(&pages,policy,&config,&budget,&||Ok(())).map_err(failure)?;assert_eq!(data.sites(),expected.run.sites.as_slice(),"all ordered original sites {kind}/{case}");assert_eq!(data.allow_used(),expected.allow_used.as_slice(),"all ordered original ALLOW {kind}/{case}");assert_eq!(data.notes(),expected.run.notes.as_slice());for(site,text)in data.sites().iter().zip(data.source_text()){assert_eq!(*text,old.tree.site_text(&site.rel,site.line as usize));}let empty=Default::default();let scope=config.borrowed_report_scope(name,"sys").unwrap_or(&empty);let actual=dq_analyze::policy_finish::finish_report(policy.metadata(),scope,&Text(&data),lint::Run{sites:data.sites().to_vec(),notes:data.notes().to_vec()},data.allow_used().to_vec(),Default::default(),&root,&None,true,|_,_,_|panic!("actual Sites lint has no custom hook"),|_,_|false);assert_eq!(record(&actual),record(&expected),"whole independent original/native report {kind}/{case}");println!("EXPIRY_WHOLE_ORIGINAL_NATIVE={}",serde_json::json!({"kind":kind,"case":case,"record":record(&actual)}));}}Ok(())}
